+			const descriptor = Object.getOwnPropertyDescriptor(current, slot);
+			if (descriptor !== undefined) {
+				if (typeof descriptor.get === "function" || typeof descriptor.set === "function") return true;
+				break;
+			}
+			current = Object.getPrototypeOf(current);
+		}
+	}
+	return false;
+}
