+			return true;
+		for (const childKey of Object.keys(value)) {
+			if (skipStructuredContent && childKey === "structuredContent") continue;
+			if (!nodeAtomic && TRANSIENT_PERSISTENCE_KEYS.includes(childKey)) continue;
