+	value: unknown;
+	key: string | undefined;
+	isTopLevelToolResultDetails: boolean | undefined;
+	atomic: boolean;
+	/** The object nodes on this node's path, innermost first, for cycle detection. */
+	parent: PathNode | undefined;
